SELECT o.*, u.username FROM orders o JOIN users u ON o.user_id = u.id
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
AND o.status = #{status}
ORDER BY
o.created_at ASC o.total_amount DESC o.total_amount ASC o.created_at DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM orders o JOIN users u ON o.user_id = u.id
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%'))
AND o.status = #{status}
